            fi = fl >> 1
            if fi != 0 and not aig.is_pi[fi] and fi not in reach:
                stack.append(fi)
    return reach


def aig_simulate(aig: Aig, n_words: int, seed: int) -> np.ndarray:
    """Bit-parallel sim of every AIG node: returns sig[node] = (n_words,) uint64.
    PIs get random words; node 0 (const 0) stays all-zero."""
    n = len(aig.fanin0)
    sig = np.zeros((n, n_words), dtype=np.uint64)
    rng = np.random.default_rng(seed)
    f0, f1, ispi = aig.fanin0, aig.fanin1, aig.is_pi
    for i in range(n):
        if ispi[i]:
            sig[i] = np.frombuffer(rng.bytes(n_words * 8), dtype=np.uint64)
    for i in range(1, n):
        if ispi[i]:
            continue
        a, b = f0[i], f1[i]
        sa = sig[a >> 1]
        if a & 1:
            sa = np.invert(sa)
        sb = sig[b >> 1]
        if b & 1:
            sb = np.invert(sb)
        sig[i] = sa & sb
    return sig


def fraig(aig: Aig, outputs: list[tuple[str, int]], n_words: int = 16,
          seed_a: int = 12345, seed_b: int = 67890
          ) -> tuple[Aig, list[tuple[str, int]], int]:
    """One round of simulation-guided functional merging (FRAIG).

    Nodes with identical canonical simulation signatures are candidate-equivalent;
    each candidate is confirmed against an INDEPENDENT vector set before merging
    (signature alone is never trusted). Confirmed nodes are merged into the
    lowest-index representative (possibly the constant node or a PI) by rebuilding
    the AIG through strash, which also re-canonicalizes and cascades (e.g. XOR
    with a now-constant input collapses). Returns (new_aig, new_outputs, merged).
    """
    reach = reachable_ands(aig, outputs)
    n = len(aig.fanin0)
    one = np.uint64(1)

    sig = aig_simulate(aig, n_words, seed_a)
    cand = [0]
    for i in range(1, n):
        if aig.is_pi[i] or i in reach:
            cand.append(i)
    buckets: dict[bytes, list[int]] = defaultdict(list)
    for i in cand:  # increasing index -> member lists stay sorted
        s = sig[i]
        canon = np.invert(s) if (s[0] & one) else s
        buckets[canon.tobytes()].append(i)

    def pol(s: np.ndarray) -> bool:
        return bool(s[0] & one)

    sig2 = aig_simulate(aig, n_words, seed_b)
    merge: dict[int, tuple[int, bool]] = {}
    for members in buckets.values():
        if len(members) < 2:
            continue
        rep = members[0]
        prep1 = pol(sig[rep])
        srep2 = sig2[rep]
        nsrep2 = np.invert(srep2)
        for m in members[1:]:
            rel = pol(sig[m]) ^ prep1            # m == rep ^ rel  (per seed_a)
            target = nsrep2 if rel else srep2
            if np.array_equal(sig2[m], target):  # confirm under seed_b
                merge[m] = (rep, rel)
    if not merge:
        return aig, outputs, 0

    new = Aig()
    new_lit = [0] * n  # new literal for each old node index
    for i in range(1, n):
        if aig.is_pi[i]:
            new_lit[i] = new.pi(aig.pi_name[i])
